#!/usr/bin/env python3
"""Validate fixed native-iteration board measurements, including all rejected decisions."""
from pathlib import Path
import hashlib,json,statistics
from gset_model import ROOT,load,cut
out=ROOT/'results/iterations';protocol=json.loads((out/'protocol.json').read_text());plan=json.loads((out/'board/plan.json').read_text());m=plan['build']
assert protocol['graphs']==plan['names']and protocol['seeds']==plan['seeds']and protocol['iteration_budget']==plan['iteration_budget']
expected={f'{name}_seed{seed}.json'for name in plan['names']for seed in plan['seeds']}
assert {p.name for p in (out/'board').glob('G*_seed*.json')}==expected
assert m['abi']=='0x49545231' and all(hashlib.sha256((ROOT/n).read_bytes()).hexdigest()==h for n,h in m['sources'].items())
assert plan['runner_sha256']==hashlib.sha256((ROOT/'scripts/run_iterations_board.py').read_bytes()).hexdigest()
rows=[]
for name in plan['names']:
 q,meta=load(ROOT/'python_code/problems'/name);runs=[]
 for seed in plan['seeds']:
  p=out/'board'/f'{name}_seed{seed}.json';d=json.loads(p.read_text())
  assert d['kind']=='gset_board_native_iteration_budget' and d['seed']==seed and d['graph']==meta
  assert d['iterations']==d['requested_iterations']==protocol['iteration_budget']and d['budget_reached']
  assert d['accepted_flips']+d['rejected_iterations']==d['iterations']
  assert d['cycles']==d['iterations']+6*d['accepted_flips']
  assert d['clock_mhz']<=m['requested_clock_mhz'] and d['cooling_period']==protocol['cooling_period_active_cycles']
  assert d['artifacts']==m['artifacts']and d['runner_sha256']==plan['runner_sha256']and d['model_sha256']==plan['model_sha256']
  assert abs(d['hardware_seconds']-d['cycles']/(d['clock_mhz']*1e6))<1e-10
  assert d['assignment_verified']and cut(q,d['assignment'])==d['best_cut']
  edge_score=sum(int(w)for line in (ROOT/'python_code/problems'/name).read_text().splitlines()[1:]if line.strip()for a,b,w in [line.split()]if d['assignment'][int(a)-1]!=d['assignment'][int(b)-1]);assert edge_score==d['best_cut']
  for t in d['targets']:
   assert t['reached']==(d['best_cut']>=t['cut'])
   if t['reached']:assert 0<t['first_hit_cycle']<=d['cycles']and abs(t['hardware_seconds']-t['first_hit_cycle']/(d['clock_mhz']*1e6))<1e-10
  runs.append({'seed':seed,'iterations':d['iterations'],'accepted_flips':d['accepted_flips'],'rejected_iterations':d['rejected_iterations'],'cycles':d['cycles'],'hardware_seconds':d['hardware_seconds'],'host_run_interval_seconds':d['host_run_interval_seconds'],'host_initialization_seconds':d['host_initialization_seconds'],'best_cut':d['best_cut'],'file':str(p.relative_to(ROOT)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
 rows.append({'graph':name,'iterations_per_run':protocol['iteration_budget'],'seeds':plan['seeds'],'median_seconds':statistics.median(r['hardware_seconds']for r in runs),'seconds_range':[min(r['hardware_seconds']for r in runs),max(r['hardware_seconds']for r in runs)],'accepted_flips_range':[min(r['accepted_flips']for r in runs),max(r['accepted_flips']for r in runs)],'cut_range':[min(r['best_cut']for r in runs),max(r['best_cut']for r in runs)],'runs':runs})
summary={'status':'Verified fixed native arbitration-iteration measurements','iteration_definition':m['iteration_definition'],'iteration_budget':protocol['iteration_budget'],'clock_mhz':plan['clock_request_mhz'],'rows':rows,'cycle_identity':'active_cycles = iterations + 6 * accepted_flips','comparison_status':'Reported fixed-budget FPGA runtime. Numeric Fig S3 iteration count and equivalent SpiNNaker2 iteration semantics remain unconfirmed; no matched platform speedup ratio.','timing_boundary':'Active FPGA compute, including accepted-update drain; excludes bitstream/graph upload and state initialization.'}
(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');(ROOT/'demo/iterations.js').write_text('/* Generated by scripts/summarize_iterations.py from checked board data. */\nwindow.QUBO_ITERATIONS='+json.dumps(summary,separators=(',',':'))+';\n')
print('PASS fixed iterations:',len(expected),'board runs')
for r in rows:print(r['graph'],'median seconds',r['median_seconds'],'flips',r['accepted_flips_range'],'cuts',r['cut_range'])
